import hashlib
import hmac
import os
import re
import sqlite3
import unicodedata
from functools import wraps
from flask import Flask, request, jsonify, g, session
import secrets

app = Flask(__name__)
app.secret_key = os.urandom(32)

DB_PATH = '/tmp/authservice.db'

# Username validation: only ASCII alphanumeric, underscore, 3-32 chars
USERNAME_PATTERN = re.compile(r'^[a-zA-Z0-9_]{3,32}$')

# Reserved/admin usernames that cannot be registered
RESERVED_NAMES = frozenset(['admin', 'root', 'system', 'administrator', 'moderator'])

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user',
        email TEXT,
        display_name TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS sessions (
        token TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    # Create admin user
    admin_hash = hashlib.pbkdf2_hmac('sha256', b'admin_secret_pw', os.urandom(16), 100000).hex()
    try:
        db.execute("INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)",
                   ('admin', admin_hash, 'admin'))
    except sqlite3.IntegrityError:
        pass
    db.commit()
    db.close()

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    h = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return salt.hex() + ':' + h.hex()

def verify_password(stored, password):
    parts = stored.split(':')
    if len(parts) != 2:
        return False
    salt = bytes.fromhex(parts[0])
    expected = parts[1]
    h = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(h.hex(), expected)

def validate_username(username):
    """Validate username meets security requirements.
    Must be ASCII alphanumeric/underscore, 3-32 chars, not reserved."""
    if not username or not isinstance(username, str):
        return False, "Username is required"
    if not USERNAME_PATTERN.match(username):
        return False, "Username must be 3-32 alphanumeric characters or underscores"
    if username.lower() in RESERVED_NAMES:
        return False, "This username is reserved"
    return True, None

def normalize_username(username):
    """Normalize username for consistent storage and lookup.
    Apply NFKC normalization for Unicode compatibility equivalence,
    then case-fold for case-insensitive matching."""
    # NFKC normalization handles compatibility decomposition
    normalized = unicodedata.normalize('NFKC', username)
    # Case-fold for case-insensitive comparison
    return normalized.casefold()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            return jsonify({'error': 'Authentication required'}), 401
        db = get_db()
        row = db.execute(
            'SELECT u.id, u.username, u.role FROM users u '
            'JOIN sessions s ON u.id = s.user_id WHERE s.token = ?',
            (token,)
        ).fetchone()
        if not row:
            return jsonify({'error': 'Invalid session'}), 401
        g.current_user = {'id': row['id'], 'username': row['username'], 'role': row['role']}
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    @require_auth
    def decorated(*args, **kwargs):
        if g.current_user.get('role') != 'admin':
            return jsonify({'error': 'Admin access required'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    if len(password) < 8:
        return jsonify({'error': 'Password must be at least 8 characters'}), 400

    # Step 1: Validate the username format and check reserved names
    valid, error = validate_username(username)
    if not valid:
        return jsonify({'error': error}), 400

    # Step 2: Normalize for storage (ensures consistent lookups)
    storage_name = normalize_username(username)

    # Step 3: Store the normalized username
    password_hash = hash_password(password)
    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)',
            (storage_name, password_hash, 'user')
        )
        db.commit()
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already taken'}), 409

    return jsonify({'message': 'Registration successful', 'username': storage_name}), 201

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    # Normalize for lookup
    lookup_name = normalize_username(username)

    db = get_db()
    user = db.execute(
        'SELECT id, username, password_hash, role FROM users WHERE username = ?',
        (lookup_name,)
    ).fetchone()

    if not user or not verify_password(user['password_hash'], password):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = secrets.token_hex(32)
    db.execute('INSERT INTO sessions (token, user_id) VALUES (?, ?)',
               (token, user['id']))
    db.commit()

    return jsonify({'token': token, 'role': user['role']}), 200

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    db = get_db()
    user = db.execute(
        'SELECT username, role, email, display_name FROM users WHERE id = ?',
        (g.current_user['id'],)
    ).fetchone()
    return jsonify(dict(user)), 200

@app.route('/api/admin/users', methods=['GET'])
@require_admin
def list_users():
    db = get_db()
    users = db.execute('SELECT id, username, role, email FROM users').fetchall()
    return jsonify([dict(u) for u in users]), 200

@app.route('/api/admin/promote', methods=['POST'])
@require_admin
def promote_user():
    data = request.get_json()
    target = data.get('username', '')
    lookup = normalize_username(target)
    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE username = ?', ('admin', lookup))
    db.commit()
    return jsonify({'message': f'User {lookup} promoted to admin'}), 200

if __name__ == '__main__':
    init_db()
    app.run(debug=False, host='127.0.0.1', port=5000)
